#include <iostream>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <thread>

std::mutex m;
std::condition_variable cv;
std::queue<int> q;
bool done = false;
int consumed = 0;

void consumer() {
    while (true) {
        std::unique_lock<std::mutex> lk(m);
        cv.wait(lk, []{ return !q.empty() || done; });   // 谓词：防虚假唤醒
        while (!q.empty()) { q.pop(); ++consumed; }
        if (done && q.empty()) break;
    }
}

int main() {
    std::thread c(consumer);
    {
        std::lock_guard<std::mutex> lk(m);
        for (int i = 0; i < 5; ++i) q.push(i);
    }
    cv.notify_all();
    {
        std::lock_guard<std::mutex> lk(m);
        done = true;
    }
    cv.notify_all();
    c.join();
    std::cout << "consumed=" << consumed;   // 5，确定性
}
